def subpaths_for_path_range(path_range, hardening_chars="'pH"):
    paths = []
    for path in path_range.split("/"):
        if "-" not in path:
            continue
        start, end = path.split("-")
        for i in range(int(start), int(end) + 1):
            hardening = ""
            for char in hardening_chars:
                if char in start:
                    hardening += "H"
                elif char in end:
                    hardening += "p"
            paths.append("{}{}".format(i, hardening))
    return iter(paths)
