def get(self):
    # Check if the object exists
    obj = self._storage.get(self._id)
    if not obj:
        raise errors.NotFoundError("Object does not exist")

    # Check if the object has been modified
    last_modified = request.headers.get("If-Modified-Since")
    if last_modified and obj["last_modified"] <= last_modified:
        raise errors.NotModifiedError("Object is unchanged")

    # Check for partial fields
    field_list = request.args.getlist("fields[]")
    if field_list:
        obj = self._storage.extract(obj, field_list)

    # Add a timestamp header and a cache header to the response
    headers = {
        "Last-Modified": obj["last_modified"],
        "Cache-Control": f"max-age={self._cache_timeout}"
    }
    return Response(obj, 200, mimetype="application/json", headers=headers)

