def get_directory_modules(directory):
    local_modules = []
    if len(local_modules) > 0:
        if directory == os.path.dirname(os.path.abspath(local_modules[0][1])):
            return local_modules
    if not os.path.isdir(directory):
        raise ValueError("{} is not a valid directory.".format(directory))
