"""
Expands non-nested lists, dicts, and tuples in a DataFrame into separate columns with a prefix. It iterates over each column in the DataFrame and checks if the values in the column are of the specified types. If they are, it expands the values into separate columns with a prefix based on the original column name.
:param df: pd.DataFrame. The DataFrame to be expanded.
:param types: Any. A list of types to expand. It defaults to [list, dict, tuple] if not specified.
:return: pd.DataFrame. The DataFrame with the expanded columns.
"""
if types is None:
    types = [list, dict, tuple]

for col in df.columns:
    column = df[col]
    for t in types:
        if column.dtype == t:
            expanded_column = []
            for val in column:
                if isinstance(val, t):
                    expanded_column += [
                        str(v) + "_" + str(i) for i, v in enumerate(val)
                    ]
                else:
                    expanded_column.append(str(val))
            df = pd.concat(
                [df, pd.DataFrame({col + "_expanded": expanded_column})], axis=1
            )
            df = df.drop(columns=[col])
            break

return df

