    main_type, sub_type = self.split("/")
    params = {}
    for param in self.parameters:
        if param.startswith("q"):
            params["q"] = float(param[2:])
    # main type
    if main_type == "*/*":
        return 1
    elif main_type == "application/*":
        return 2
    elif main_type == "audio/*":
        return 3
    elif main_type == "video/*":
        return 4
    # sub type
    if sub_type == "*":
        return 100
    elif sub_type == "*+xml":
        return 101
    # parameters
    if params.get("q") is not None:
        return 200 + (params["q"] * 100)
    else:
        return 300

