```
import time

class BufferedSocket(object):
    def __init__(self, socket, buffer_size=4096):
        self.socket = socket
        self.buffer = bytearray()
        self.buffer_size = buffer_size

    def recv(self, size, flags=0, timeout=_UNSET):
        if not self.buffer:
            # Check if there are any remaining bytes in the buffer
            # If there are none, perform a single receive operation on the socket
            # to retrieve the requested data and store it in the buffer
            try:
                data = self.socket.recv(size, flags)
            except socket.timeout as e:
                raise TimeoutError('Recv timed out') from e
            else:
                if len(data) < size:
                    # If the received data is less than the requested size,
                    # store the excess bytes in the buffer for future use
                    self.buffer += data[size:]
                return data[:size]
        elif size > len(self.buffer):
            # Check if there are enough bytes in the internal buffer to fulfill the request
            # If not, perform a single receive operation on the socket
            # to retrieve the requested data and store it in the buffer
            try:
                data = self.socket.recv(size - len(self.buffer), flags)
            except socket.timeout as e:
                raise TimeoutError('Recv timed out') from e
            else:
                if len(data) < size - len(self.buffer):
                    # If the received data is less than the requested size,
                    # store the excess bytes in the buffer for future use
                    self.buffer += data[size:]
                return self.buffer[:size]
        else:
            # If there are enough bytes in the internal buffer to fulfill the request,
            # return the requested data from the buffer
            data = self.buffer[:size]
            del self.buffer[:size]
            return data
```
