def __init__(self, stream, encoding="utf-8"):
    self.stream = stream
    self.encoding = encoding
    self.buffer = bytearray()
    self.read_offset = 0
    self.buffer_end_offset = 0
    self.headers = {}
    self.expected_content_length = -1
    self.DEFAULT_BUFFER_SIZE = 8192
    self.MAX_BUFFER_SIZE = 65536
    self.read_state = ReadState.Header

def read_next_chunk(self) -> bool:
    """Read a chunk of data from the output stream and store it in a buffer."""
    try:
        data = self.stream.read(self.DEFAULT_BUFFER_SIZE)
        if not data:
            raise EOFError("Stream is empty")
        else:
            # Check if buffer needs to be resized.
            if len(self.buffer) + self.buffer_end_offset == self.MAX_BUFFER_SIZE:
                # Resize the buffer.
                new_buffer = bytearray(max(len(data), self.DEFAULT_BUFFER_SIZE))
                new_buffer[: self.buffer_end_offset] = self.buffer[
                    self.read_offset : self.buffer_end_offset
                ]
                # Point to the new buffer.
                self.buffer = new_buffer
            # Append data to the buffer.
            self.buffer[
                self.buffer_end_offset : self.buffer_end_offset + len(data)
            ] = data
            self.buffer_end_offset += len(data)
            return True
    except AttributeError:
        raise EOFError("Stream is closed")

def read_next_message(self):
    """Read a single JSON RPC message from the buffer."""
    try:
        if self.read_state == ReadState.Header:
            # Check if we need to resize the buffer.
            if len(self.buffer) - self.read_offset < 4:
                return None
            else:
                # Check for newline characters.
                while True:
                    index = self.buffer[self.read_offset :].find(b"\n")
                    if index != -1:
                        break
                    else:
                        return None
                self.read_offset += index + 1
        elif self.read_state == ReadState.Content:
            # Check if we need to resize the buffer.
            if len(self.buffer) - self.read_offset < self.expected_content_length:
                return None
            else:
                # Check for newline characters.
                while True:
                    index = self.buffer[self.read_offset :].find(b"\n")
                    if index != -1:
                        break
                    else:
                        return None
                self.read_offset += index + 1
        # Read the message from the buffer.
        message = json.loads(
            self.buffer[
                self.read_offset : self.read_offset + self.expected_content_length
            ].decode(self.encoding)
        )
        self.read_offset += self.expected_content_length
        return message
    except ValueError:
        # Content length contained invalid literal for int.
        self.trim_buffer_and_resize(self.read_offset + 4)
        raise

def trim_buffer_and_resize(self, bytes_to_remove):
    """Trim the buffer by the passed in bytes_to_remove by creating a new buffer that is at a minimum the default max size."""
    current_buffer_size = len(self.buffer)
    # Create a new buffer with either minumum size or leftover size.
    new_buffer = bytearray(
        max(current_buffer_size - bytes_to_remove, self.DEFAULT_BUFFER_SIZE)
    )
    # if we have content we did not read, copy that portion to the new buffer.
    if bytes_to_remove <= current_buffer_size:
        new_buffer[: self.buffer_end_offset - bytes_to_remove] = self.buffer[
            bytes_to_remove : self.buffer_end_offset
        ]
    # Point to the new buffer.
    self.buffer = new_buffer

