    """Verify an SSH signature of the specified data using this key."""
    # Decode the signature packet
    signature = self._decode_signature(sig)

    # Check if the signature algorithm is supported
    if signature.algorithm not in self.supported_algorithms:
        return False

    # Perform the actual verification using the appropriate method
    if signature.algorithm == "rsa-sha2-256":
        return self._verify_rsa_sha2_256(data, signature)
    elif signature.algorithm == "rsa-sha2-512":
        return self._verify_rsa_sha2_512(data, signature)
    else:
        raise NotImplementedError("Unsupported algorithm")
