import copy
from collections import deque

def default_visit(path, key, value):
    return key, value

def default_enter(value):
    new_parent = {}
    iter_values = iter([]) if isinstance(value, set) else iter([])
    return new_parent, iter_values

def default_exit(path, key, value, new_parent, new_values):
    return new_parent

def remap(root, visit=default_visit, enter=default_enter, exit=default_exit, **kwargs):
    if isinstance(root, (list, tuple, set)):
        iter_value = iter(root)
    else:
        iter_value = root.items() if isinstance(root, dict) else root

    queue = deque([iter_value])
    while queue:
        iter_current = queue.popleft()
        for key, value in iter_current:
            new_parent, new_values = enter(value)
            if new_values is False:
                continue
            else:
                new_key, new_value = visit(path, key, value)
                if new_value is True:
                    new_parent[new_key] = value
                elif isinstance(value, (list, tuple, set)):
                    new_parent[new_key] = copy.deepcopy(value)
                else:
                    new_parent[new_key] = {}
                if isinstance(new_values, (list, tuple, set)):
                    queue.appendleft(iter(new_values))
                elif isinstance(new_values, dict):
                    queue.appendleft(new_values)
                else:
                    new_parent = exit(path, key, value, new_parent, new_values)
                    return new_parent
