def read(self, amt=None):
    if not self.files:
        return ''

    data = []
    for file in self.files:
        if file.closed:
            continue

        try:
            chunk = file.read(amt)
        except IOError as e:
            if e.errno == errno.EAGAIN or e.errno == errno.EWOULDBLOCK:
                continue
            raise

        if not chunk:
            break

        data.append(chunk)

