import configparser

def _load(files, defaults, overrides):
    # Create a RawConfigParser instance with inline comment prefixes
    parser = configparser.RawConfigParser(allow_no_value=True)
    # Load the configuration from the builtin defaults
    for default in defaults:
        parser.read_string(default)
    # Iterate over the files and load the configuration from each file
    for file in files:
        if os.path.isdir(file):
            for conf_file in os.listdir(file):
                if conf_file.endswith('.conf'):
                    parser.read(os.path.join(file, conf_file))
        else:
            parser.read(file)
    # Create a dictionary where each section is a key and the corresponding value is a dictionary of key-value pairs for that section
    raw_config = {}
    for section in parser.sections():
        raw_config[section] = {key: parser.get(section, key) for key in parser.options(section)}
    # Update the raw_config dictionary with any command line overrides specified in the overrides list
    if overrides is not None:
        for section, key, value in overrides:
            if section not in raw_config:
                raw_config[section] = {}
            raw_config[section][key] = value
    return raw_config
```
