def compute_likelihood_window(window, prior_probs, trans_probs, use_start_token=True, use_end_token=True, start_token=None, end_token=None):
    likelihood = 1.0

    # Calculate the likelihood of each command in the window
    for cmd in window:
        likelihood *= prior_probs[cmd]

    # Calculate the transition probability between adjacent commands
    for i in range(len(window) - 1):
        likelihood *= trans_probs[(window[i], window[i + 1])]

    # Adjust the likelihood based on whether start and end tokens were used
    if use_start_token:
        likelihood /= prior_probs[start_token]

    if use_end_token:
        likelihood /= prior_probs[end_token]

    return likelihood

