import pickle
from typing import Dict

class NdarrayContainer:
    def __init__(self, payload: Payload):
        self.payload = payload

    @classmethod
    def from_payload(cls, payload: Payload) -> ext.NpNDArray:
        if 'format' not in payload or payload['format'] != 'pickle5':
            return pickle.loads(payload['data'])
        else:
            with open('payload', 'wb') as f:
                f.write(payload['data'].encode())
            with open('payload', 'rb') as f:
                np_array = pickle.load(f)
            os.remove('payload')
            return np_array
```
Note that this method uses the `pickle5` library to decode the payload data if it is in the "pickle5" format, and otherwise uses the standard Python `pickle` module to load the ndarray from the payload.

