def disconnect(self, receiver=None, name=None, sender=None):
    if receiver is None and name is None:
        raise ValueError("Must provide either a receiver or a name")
    elif receiver is not None and name is not None:
        raise ValueError("Cannot provide both a receiver and a name")

    if sender is not None and not isinstance(sender, Signal):
        raise TypeError("Sender must be an instance of the Signal class")

    # Find the index of the receiver in the list of receivers
    if name is not None:
        for i, (rname, rreceiver, rsender) in enumerate(self.receivers):
            if rname == name and (sender is None or sender == rsender):
                break
        else:
            raise ValueError("No receiver with the specified name")
    elif receiver is not None:
