def filter_for_lineage(self, targets: Iterable[_TR], check_against: Optional[str], include_dependencies: bool = False) -> Tuple[_TR, ...]:
    if check_against is None:
        return tuple(targets)

    # Get the revision map for the specified revision number.
    revision_map = self.revision_maps[check_against]

    # Filter the targets based on their lineage.
    filtered_targets = []
    for target in targets:
        if revision_map.has_dependency(target):
            filtered_targets.append(target)

        if include_dependencies and revision_map.has_dependent(target):
            filtered_targets.extend(revision_map.get_dependent(target))

    return tuple(filtered_targets)
