    # Get set of recipe/dependency names, clean up and add bootstrap deps:
    names = set(names)
    if bs is not None:
        names.add('android')
    if blacklist is not None:
        names -= blacklist
    # Check for conflicts and generate all possible order graphs:
    recipes_and_deps = []
    for name in names:
        try:
            recipe = Recipe.get_recipe(name, ctx)
        except ValueError:
            continue
        deps = [dep for dep in recipe.depends]
        if deps and deps[0] == 'android':
            deps = ['android'] + deps
        if deps:
            recipes_and_deps.append((recipe, deps))
    order_graphs = []
    for i in range(len(recipes_and_deps)):
        for j in range(i + 1, len(recipes_and_deps)):
            if recipes_and_deps[i][1] == recipes_and_deps[j][1]:
                order_graphs.append((i, j))
    # Convert each order graph into a linear list and sort them based on preference:
    sorted_order_graphs = []
    for i in range(len(recipes_and_deps)):
        sorted_order_graphs.append([])
    for i, j in order_graphs:
        sorted_order_graphs[i].append(j)
    # Return the chosen order, along with the corresponding recipes, python modules, and bootstrap instance:
    chosen_order = []
    recipes = []
    modules = []
    bootstrap = None
    for i in range(len(recipes_and_deps)):
